export function formatValue(v){return v==null?'—':typeof v==='number'?v.toLocaleString('en-US',{maximumFractionDigits:3}):String(v);}
export function carrierMatches(c,s){if(s.country&&c['Aircraft Nation']!==s.country)return false;if(s.aircraft&&!`${c.Aircraft} ${c['Aircraft ID']}`.toLowerCase().includes(s.aircraft.toLowerCase().trim()))return false;const br=c[s.mode];if(s.min!==''&&(br==null||br<Number(s.min)))return false;if(s.max!==''&&(br==null||br>Number(s.max)))return false;return true;}
export function brSummary(carriers,mode){const values=carriers.map(c=>c[mode]).filter(v=>typeof v==='number').sort((a,b)=>a-b),n=values.length;return n?{min:values[0],max:values[n-1],median:n%2?values[(n-1)/2]:(values[n/2-1]+values[n/2])/2}:{min:null,max:null,median:null};}
export function filterWeapons(weapons,carrierMap,s){const terms=s.search.toLowerCase().trim().split(/\s+/).filter(Boolean);return weapons.filter(w=>{const carriers=carrierMap.get(w.File)||[];if(s.category&&w.Category!==s.category)return false;for(const [filter,key] of [['origin','Nation'],['guidance','Guidance Family'],['fox','Fox Class'],['mounted','Air-Launched'],['variants','Is Variant']])if(s[filter]&&w[key]!==s[filter])return false;if((s.country||s.aircraft||s.min!==''||s.max!=='')&&!carriers.some(c=>carrierMatches(c,s)))return false;if(terms.length){const text=[w.Weapon,w['Full Name'],w.File,w.Nation,w.Category,w['Guidance Family'],w['Fox Class'],...carriers.map(c=>c.Aircraft+' '+c['Aircraft ID'])].join(' ').toLowerCase();if(!terms.every(t=>text.includes(t)))return false;}if(s.field){const v=w[s.field],missing=v==null||v==='';if(s.operator==='present'&&missing)return false;if(s.operator==='missing'&&!missing)return false;if(!['present','missing'].includes(s.operator)&&s.value.trim()!==''){if(missing)return false;if(s.operator==='contains'&&!String(v).toLowerCase().includes(s.value.toLowerCase().trim()))return false;if(s.operator==='equals'&&String(v).toLowerCase()!==s.value.toLowerCase().trim())return false;if(['gte','lte'].includes(s.operator)){const n=Number(s.value);if(typeof v!=='number'||!Number.isFinite(n))return false;if(s.operator==='gte'&&v<n)return false;if(s.operator==='lte'&&v>n)return false;}}}return true;});}
